package com.hashem.sms; import android.content.*;import android.app.PendingIntent;import android.telephony.*;import java.util.*; public class ScheduleReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String a=i.getStringExtra("address"),b=i.getStringExtra("body");if(a==null)return;SmsManager s=SmsManager.getDefault();ArrayList<String> p=s.divideMessage(b);ArrayList<PendingIntent> sent=new ArrayList<>();for(int n=0;n<p.size();n++)sent.add(PendingIntent.getBroadcast(c,(int)System.nanoTime(),new Intent(c,SentReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));s.sendMultipartTextMessage(a,null,p,sent,null);new Db(c).addMessage(a,b,"out","scheduled");}}
